mapper.select:
SELECT
	e.emp_id AS value,
	CONCAT(e.emp_lname, e.emp_fname) AS lavel
FROM
	madaka.employee_mst e
	LEFT JOIN madaka.team_mst t ON e.team_id = t.team_id
WHERE
    (
        /* ① リーダー or チーフ → 同じチームの社員 */
		(#{role} IN ('2', '3')
			AND e.team_id = #{teamId}
		)
        OR
        /* ② マネージャー or アシスタントマネージャー → 同じユニットの社員 */
		(#{role} IN ('4', '5')
            AND t.unit_no = #{unitNo}
        )
        OR
        /* ③ 部署が総務 → 全取得 */
        (#{departmentId} = '0')
    );

SELECT lat.late_id, emp.emp_id, CONCAT(emp.emp_lname, ' ', emp.emp_fname) AS emp_name, lat.late_datetime, lat.late_reason, lat.late_min, lat.train_delay_min, lat.train_id, tra.train_name, lat.start_time, lat.update_datetime, lat.note FROM madaka.late_his_tbl AS lat INNER JOIN madaka.employee_mst AS emp ON lat.emp_id = emp.emp_id LEFT JOIN madaka.train_mst AS tra ON lat.train_id = tra.train_id
AND lat.late_datetime >= #{fromDate}
AND lat.late_datetime <= #{toDate}
AND lat.emp_id = #{employeeId}
AND lat.late_reason = #{reason}
ORDER BY lat.late_datetime DESC
